+
+  testWidgets('in-flight tool — running row above the composer (dark)', (
+    tester,
+  ) async {
+    await _pumpStatusFrame(
+      tester,
+      rows: [
+        FahChatMessage(role: 'user', content: 'run the test suite for me'),
+        FahChatMessage(
+          role: 'system',
